import{_ as a,o as e,c as r,a4 as d}from"./chunks/framework.BybBnFXO.js";const u=JSON.parse('{"title":"蛋面与雕刻","description":"","frontmatter":{"title":"蛋面与雕刻","cutting":"cabochon-and-carving"},"headers":[],"relativePath":"zh/cutting/cabochon-and-carving.md","filePath":"zh/cutting/cabochon-and-carving.md","lastUpdated":1785888308000}'),n={name:"zh/cutting/cabochon-and-carving.md"};function o(i,t,c,h,l,s){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="蛋面与雕刻" tabindex="-1">蛋面与雕刻 <a class="header-anchor" href="#蛋面与雕刻" aria-label="Permalink to &quot;蛋面与雕刻&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>不透明或具特殊光学效应的宝石不适合刻面——改用蛋面（凸圆打磨）或 雕刻。蛋面完美呈现星光、猫眼、月光效应；玉石、玛瑙则走雕刻路线。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>单蛋面/双蛋面 (single/double cabochon)：决定星光与猫眼清晰度。</li><li>星光效应需定向打磨——使金红石针平行台面。</li><li>猫眼效应同理，针状包裹体需定向于弧面轴线。</li><li>玉石雕刻（翡翠、软玉、绿松石）考验材料纹理与色彩层次运用。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>切工</th><th>备注</th></tr></thead><tbody><tr><td>ruby</td><td>Star cabochon</td><td>—</td></tr><tr><td>tigers-eye</td><td>Cat&#39;s-eye cabochon</td><td>—</td></tr><tr><td>jadeite</td><td>Carved pendant</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">切割总览</a>。</em></p>',8)])])}const _=a(n,[["render",o]]);export{u as __pageData,_ as default};
